import{S as i,o as a,c as o,a9 as n,B as l}from"./chunks/framework.DxG24V0C.js";const p="/agentsrc/images/codex/03-four-pillars.svg",r="/agentsrc/images/codex/03-slot-layout.svg",h="/agentsrc/images/codex/03-fragment-injection.svg",g=JSON.parse('{"title":"Codex 上下文管线：几十种状态片段如何拼装才不会乱？","description":"","frontmatter":{"title":"Codex 上下文管线：几十种状态片段如何拼装才不会乱？"},"headers":[],"relativePath":"codex/03-context.md","filePath":"codex/03-context.md","lastUpdated":1788847143000}'),d={name:"codex/03-context.md"},u=Object.assign(d,{setup(c){const s=[{question:"为什么 Codex 不能简单地将所有动态状态（如当前工作目录、Shell 状态）直接拼接到 System Prompt 的末尾？",options:["因为这会导致 Rust 编译器的字符串生命周期检查失败，引发内存泄漏","因为动态状态的高频变化会破坏大模型的前缀缓存机制，导致成本飙升","因为 System Prompt 的长度被硬编码限制在 1024 个字符以内，无法容纳","因为动态状态包含大量不可见的控制字符，会导致大模型解析 JSON 失败"],correct:1,explanation:"现代 LLM 的 Prompt Caching 通常依赖前缀的绝对一致性。如果将高频变化的动态状态与静态指令混在一起，会导致缓存命中率极低，同时也会造成模型注意力涣散。"},{question:"在 Codex 的 Prompt 组装架构中，工具的 JSON Schema 是如何传递给模型的？",options:["作为 Contextual User Slot 的一部分，与环境变量一起发送","作为 Developer Policy Slot 的一部分，放在权限说明的后面","作为 Separate Developer Slot 的独立消息发送，防止被污染","由 ToolRouter 统一管理，并直接赋值给 Prompt.tools 字段"],correct:3,explanation:"工具 Schema 并不在 Developer Slot 中。当前工具通过 built_tools 构建 ToolRouter，再由 build_prompt 放进 Prompt.tools 字段中，与文本指令分离。"},{question:"Codex 引入 ContextContributor 和 PromptFragment 机制的核心设计意图是什么？",options:["为了将超长的历史对话记录切分成多个小片段，以便在多线程中并行发送给模型","为了实现动态状态的插件化注入，使得各子系统能在运行时追加特定 Slot 的上下文","为了绕过操作系统的文件读取权限限制，将敏感文件内容伪装成内存片段传递","为了在模型生成代码时，将代码片段与普通文本分离，强制模型输出结构化 JSON"],correct:1,explanation:"系统状态是动态的。ContextContributor 允许各个子系统在运行时动态生成 PromptFragment，并根据其定义的 PromptSlot 自动注入到对应的槽位中，实现了高度的解耦。"},{question:"Codex 为什么要根据运行时的沙箱权限（如只读模式 vs 全权限模式）动态渲染不同的权限说明模板？",options:["为了将安全策略与模型认知对齐，防止模型在不知情的情况下尝试越权操作陷入死循环","为了减少向模型发送的 Token 数量，只读模式下的模板比全权限模式的模板字数更少","为了向用户隐藏系统底层的沙箱实现细节，使得 TUI 界面的渲染逻辑更加简洁","为了兼容不同厂商的大模型，某些开源模型无法理解全权限模式下的复杂系统指令"],correct:0,explanation:"如果模型不知道自己处于只读沙箱中，它可能会不断尝试生成写入文件的工具调用，然后被底层沙箱拦截，导致死循环。动态渲染权限说明解决了模型认知与底层物理限制的对齐问题。"},{question:"在 run_turn 流程中，record_context_updates_and_set_reference_context_item 函数的主要作用是什么？",options:["强制清空所有历史对话记录，仅保留最新的 Reference Context Item 以节省 Token","对比当前上下文与参考点，如果只有局部变化，则尝试仅发送 Settings Diff 以优化性能","将所有的 PromptFragment 序列化为 JSON 格式，并写入本地磁盘作为参考备份","检查当前上下文是否包含恶意指令，如果发现则立即抛出异常并中断 run_turn 流程"],correct:1,explanation:"为了优化性能，Codex 并不是每次都全量重新发送所有上下文。它会对比当前的上下文与上一次的参考点，尝试仅发送增量的 Settings Diff，这种精细的状态管理是维持长会话稳定性的关键。"}];return(k,e)=>{const t=i("Quiz");return a(),o("div",null,[e[0]||(e[0]=n("",53)),l(t,{questions:s})])}}});export{g as __pageData,u as default};
